[assembly: BenchmarkDotNet.Attributes.Config(typeof(Microsoft.VSDiagnostics.BenchmarkProfilerAgentConfig))]

namespace Microsoft.VSDiagnostics
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
    using BenchmarkDotNet.Configs;
    using BenchmarkDotNet.Filters;
    using BenchmarkDotNet.Jobs;
    using BenchmarkDotNet.Running;

    /// <summary>
    /// Provides the assembly level configuration for Profiler Agent sessions.
    /// This will correctly set the required Microsoft.VSDiagnostics benchmark attributes and environment variables
    /// for launching and analyzing benchmarks via the Copilot Profiler Agent.
    /// </summary>
    /// <remarks>
    /// This configuration is intended for use in environments where profiling is controlled via the Copilot Profiler Agent.
    /// </remarks>
    internal sealed class BenchmarkProfilerAgentConfig : ManualConfig, IConfigSource
    {
        private const string SessionEnvVar = "PROFILER_AGENT_SESSION";
        private const string ToolEnvVar = "PROFILER_AGENT_TOOL";
        private const string FilterEnvVar = "PROFILER_AGENT_BDN_FILTER";

        /// <summary>
        /// Initializes a new instance of the <see cref="BenchmarkProfilerAgentConfig"/> class.
        /// Configures diagnosers and filters based on environment variables.
        /// </summary>
        public BenchmarkProfilerAgentConfig()
        {
            bool agentSession = !string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(SessionEnvVar));
            if (!agentSession)
            {
                // Do nothing if the Copilot Profiler Agent did not launch the session.
                return;
            }

            // Add the diagnoser
            var tool = (Environment.GetEnvironmentVariable(ToolEnvVar) ?? "CPU").Trim().ToUpperInvariant();
            switch (tool)
            {
                case "MEMORY":
                    this.AddDiagnoser(new DotNetObjectAllocDiagnoser());
                    this.AddJob(Job.Default
                        .WithIterationCount(5)
                        .WithWarmupCount(1)
                        .WithEnvironmentVariables(VSDiagnosticsConfigurations.GetDotNetObjectAllocEnvironmentVariables())
                        .AsMutator());
                    break;

                case "INSTRUMENTATION":
                    this.AddDiagnoser(new InstrumentationDiagnoser());
                    this.AddJob(Job.Default
                        .WithEnvironmentVariables(VSDiagnosticsConfigurations.GetInstrumentationEnvironmentVariables())
                        .AsMutator());
                    break;

                case "DATABASE":
                    this.AddDiagnoser(new DatabaseDiagnoser());
                    break;

                case "COUNTERS":
                    this.AddDiagnoser(new DotNetCountersDiagnoser());
                    break;

                case "EVENTS":
                    this.AddDiagnoser(new EventsDiagnoser());
                    break;

                case "FILEIO":
                    this.AddDiagnoser(new FileIODiagnoser());
                    break;

                case "CPU":
                default:
                    this.AddDiagnoser(new CPUUsageDiagnoser());
                    break;
            }

            // Add the filter
            var filterRaw = Environment.GetEnvironmentVariable(FilterEnvVar);
            if (!string.IsNullOrWhiteSpace(filterRaw))
            {
                var names = filterRaw
                    .Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
                    .Select(s => s.Trim())
                    .Where(s => s.Length > 0)
                    .Distinct(StringComparer.Ordinal)
                    .ToArray();

                this.AddFilter(new GlobFilter(names));
            }
        }

        /// <inheritdoc />
        public IConfig Config => this;
    }
}
